use serde::{Deserialize,Serialize};
#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize)]pub struct Rgba{pub r:u8,pub g:u8,pub b:u8,pub a:u8}impl Rgba{pub const fn rgb(r:u8,g:u8,b:u8)->Self{Self{r,g,b,a:255}}#[allow(clippy::self_named_constructors)]pub const fn rgba(r:u8,g:u8,b:u8,a:u8)->Self{Self{r,g,b,a}}pub fn with_alpha(self,a:u8)->Self{Self{a,..self}}}
#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize,Default)]#[serde(rename_all="snake_case")]pub enum ThemeId{Light,#[default]Dark,GlassDark,Liquid,ClayLight,ClayDark,NeumorphicLight,NeumorphicDark}impl ThemeId{pub const ALL:[Self;8]=[Self::Light,Self::Dark,Self::GlassDark,Self::Liquid,Self::ClayLight,Self::ClayDark,Self::NeumorphicLight,Self::NeumorphicDark];pub fn name(self)->&'static str{match self{Self::Light=>"light",Self::Dark=>"dark",Self::GlassDark=>"glass_dark",Self::Liquid=>"liquid",Self::ClayLight=>"clay_light",Self::ClayDark=>"clay_dark",Self::NeumorphicLight=>"neumorphic_light",Self::NeumorphicDark=>"neumorphic_dark"}}pub fn from_name(s:&str)->Self{Self::ALL.into_iter().find(|i|i.name()==s).unwrap_or(Self::Dark)}}
